export function prefersReducedMotion(): boolean {
  if (typeof window === "undefined") return false;
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

export function fireStageTransitionConfetti(
  rootEl: HTMLElement | null,
  colors: string[],
): void {
  if (prefersReducedMotion() || !rootEl || typeof window === "undefined") return;
  void import("canvas-confetti").then((mod) => {
    const confetti = mod.default;
    const rect = rootEl.getBoundingClientRect();
    const x = (rect.left + rect.width / 2) / window.innerWidth;
    const y = (rect.top + Math.min(48, rect.height / 3)) / window.innerHeight;
    const palette = colors.length ? colors : ["#38bdf8", "#4f6df5", "#ffffff"];
    void confetti({
      particleCount: 42,
      spread: 58,
      startVelocity: 28,
      ticks: 120,
      gravity: 0.95,
      scalar: 0.9,
      origin: { x, y },
      colors: palette,
    });
  });
}

